    q16442: { h: "0669b86a3408", text: "Rolls of cloth mean the hard work of lifting, spreading and showing: would you enjoy showing cloth?" },
    q16443: { h: "83e4e2261960", text: "A dealership means rounds in the sun for test drives: would you like the rounds of drives?" },
    q16444: { h: "fd4118b3ce1e", text: "A mandi agency means standing at dawn amid the noise of bidding: would you enjoy the dawn of bidding?" },
    q16445: { h: "ee65ca7bfe9c", text: "Industrial supply means walking the rounds with a bag of catalogues: would you like walking with catalogues?" },
    q16446: { h: "7a9a1c2ac647", text: "An export desk means sitting at night over mail across time zones: could you bear the night of mail?" },
    q16447: { h: "23a1f00567a9", text: "Testing gems means seated concentration with loupe and scale: would you enjoy the concentration of testing?" },
    q16448: { h: "de5dbf95e9fc", text: "A commodity screen means an eye on every tick of the price: would you like the eye on prices?" },
    q16449: { h: "eaa0a54a39c7", text: "A scrap yard means the hard work of weighing amid the sparks of the cutter: could you bear the sparks of the yard?" },
    q16450: { h: "9b20ecbd571b", text: "A chemicals warehouse means glove work rolling drums: would you like the work of drums?" },
    q16451: { h: "f728b06f7c23", text: "Food wholesale means loading at dawn from stacks of sacks: would you enjoy loading the stacks?" },
    q16452: { h: "f078d8385da7", text: "The FMCG beat means walking with a bag from shop to shop: would you like the beat on foot?" },
    q16453: { h: "231ff19f0452", text: "A medicine van means a dash along the route counting crates: would you enjoy the route of the van?" },
    q16454: { h: "3170b662c6e6", text: "A bank counter means seated concentration counting notes: would you like the concentration of notes?" },
    q16455: { h: "a9666ac12fae", text: "Microfinance means rounds on foot for village meetings: would you enjoy the village rounds?" },
    q16456: { h: "9156e2e88616", text: "An investment desk means long sittings reading reports: would you like sitting with reports?" },
    q16457: { h: "a67ddc1dab21", text: "Broking means the tension of the screen from nine to half past three: could you bear the tension of the screen?" },
    q16458: { h: "dcb1fabd7a91", text: "A fund house means patience at the desk checking figures: would you enjoy the patience of figures?" },
    q16459: { h: "63bb90e588f9", text: "An insurance agency means evening rounds explaining from home to home: would you like the rounds of explaining?" },
    q16460: { h: "4e293dba33ab", text: "A pension desk means sitting patiently with the elderly, checking forms: would you enjoy the patience of forms?" },
    q16461: { h: "11716ab8c141", text: "A VC desk means sitting all day hearing pitches: would you like sitting through pitches?" },
    q16462: { h: "b2cf15d4bc48", text: "A PE check means nights of reading a mountain of papers: could you bear the night of papers?" },
    q16463: { h: "a4edb749f5ac", text: "Fintech support is a day at the screen with a queue of tickets: would you enjoy a day of tickets?" },
    q16464: { h: "ff1fc78d84c0", text: "A residential site means rounds in the sun showing customers round: would you like showing people round the site?" },
    q16465: { h: "561fe03a3cdd", text: "A commercial lease means the double dash of visits and desk: would you enjoy the dash of leasing?" },
    q16466: { h: "8fed3b5ad7eb", text: "An industrial shed means dusty rounds with the measuring tape: would you like the tape in the shed?" },
    q16467: { h: "0e104c5bd786", text: "Land documents mean a dash of patience in office queues: would you enjoy the patience of queues?" },
    q16468: { h: "21b95f2c016f", text: "REIT analysis means sitting at a screen of tables: would you like sitting with REIT tables?" },
    q16469: { h: "e78fb504fbb5", text: "Housing society management is a day on the stairs doing rounds of complaints: would you enjoy the rounds of complaints?" },
    q16470: { h: "f55851a474f8", text: "A property portal is a day in the vehicle on photo visits: would you like the photo visits?" },
