    q16474: { h: "828e8a0adaa4", text: "Valuation means rounds from home to home with photos and measurements: would you like the rounds of measuring?" },
    q16475: { h: "9ba3f52e6382", text: "Co-working duty means a dash on your feet setting up for guests: would you enjoy the dash for guests?" },
    q16476: { h: "3d957b7897f3", text: "Lease management means checks at the desk over the table of dates: would you like checking dates?" },
    q17384: { h: "036c7349cfa4", text: "A supermarket gives no breather from the morning rush to the night count: could you bear a day without a breather?" },
    q17385: { h: "df19088b7eb0", text: "The slow afternoons of a bookshop wait for a sale: could you put up with slow afternoons?" },
