    q17397: { h: "062bdafd94a2", text: "A gem deal ripens over weeks of testing and testing: would you count the weeks of a deal?" },
    q17398: { h: "18a7e0f73b70", text: "The red and green movement of the commodity screen makes the heart stop: could you put up with the red and green movement?" },
    q17399: { h: "92fee2510bf3", text: "The scrap market calls a new scrap price every day: could you bear a new price every day?" },
    q17400: { h: "8226adec147f", text: "The safety check of a chemical consignment stops it at the gate: could you put up with the stop at the gate?" },
