    q17402: { h: "6368b47bc205", text: "The target of the FMCG beat climbs afresh every week: could you put up with weekly targets?" },
    q17403: { h: "e6071067a221", text: "Demand for winter consignments in medicine distribution jumps suddenly: could you bear sudden demand?" },
    q17404: { h: "d4fb186426df", text: "Reminding people of instalments in bank collections is daily work: could you put up with instalment reminders?" },
    q17405: { h: "4abf7d5d7803", text: "The group meeting of microfinance has to be repeated every week: could you bear the repetition of meetings?" },
    q17406: { h: "7fb206dd04fc", text: "The market gives the fruit of investment advice over years: would you count the years to the fruit?" },
    q17407: { h: "26e7023a62db", text: "A broking customer tells you off in a falling market: could you put up with the reproach of a fall?" },
    q17408: { h: "22c14aafa404", text: "Fund performance is tested quarter by quarter: could you bear the quarterly test?" },
    q17409: { h: "6e9284d9639d", text: "An insurance claim keeps coming back for missing papers: could you put up with returned claims?" },
    q17410: { h: "307598503e42", text: "The elderly fill in pension forms at their own pace: could you bear the pace of the elderly?" },
    q17411: { h: "c1aca140457c", text: "A VC's reply stays at 'we will think and tell you' for months: could you put up with months of thinking?" },
    q17412: { h: "a6ee38b26ef0", text: "The layers of checks on a PE deal run long: could you bear the layers of a deal?" },
