    q17425: { h: "8e6f632161af", text: "Co-working seats stay half empty for months: could you bear the half-empty seats?" },
    q17426: { h: "7763b04074f2", text: "The talks for renewing a lease drag on for months: could you put up with the dragging of renewals?" },
